use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn is_valid_char(c: char) -> bool {
    c == 'H' || c == 'D'
}

spec fn is_valid_input(input: Seq<char>) -> bool {
    input.len() >= 3 &&
    input[1] == ' ' &&
    is_valid_char(input[0]) &&
    is_valid_char(input[2]) &&
    (input.len() > 3 ==> input[3] == '\n')
}

fn solve(input: Vec<char>) -> (result: Vec<char>)
    requires
        is_valid_input(input@),
    ensures
        result@.len() == 2,
        (input@[0] == input@[2]) ==> (result@[0] == 'H'),
        (input@[0] != input@[2]) ==> (result@[0] == 'D'),
        result@[1] == '\n',
{
    // We know input has at least 3 elements from precondition
    let first = input[0];
    let third = input[2];
    
    // Determine output based on comparison
    let output_char = if first == third { 'H' } else { 'D' };
    
    // Create result vector with output_char followed by newline
    let mut result = Vec::new();
    result.push(output_char);
    result.push('\n');
    
    result
}

}
